ROOT = Path(__file__).resolve().parent.parent
def head(name):
    source = (ROOT / 'originals' / name).read_text(encoding='utf-8')
    h = source.split('</head>')[0]
    h = re.sub(r'<base[^>]*>', '', h)
    h = re.sub(r'<link[^>]+(?:fonts\.google|fonts\.gstatic)[^>]*>', '', h)
    h = re.sub(r'<link[^>]+href="(?:\.\./)?css/[^>]*>', '', h)
    h = re.sub(r'<style>.*?</style>', '', h, flags=re.S)
    h = h.replace('content="noindex"', 'content="index, follow"')
    ui_styles = {'index.html': ['growth', 'discount'], 'partner-growth-programs.html': ['growth'], 'discounting.html': ['discount']}.get(name, [])
    extra = ''.join(f'\n<link rel="stylesheet" href="css/{kind}-ui.css">' for kind in ui_styles)
    return h + '\n<link rel="stylesheet" href="css/folio.css">\n<link rel="stylesheet" href="css/editorial.css">\n<link rel="stylesheet" href="css/showcase.css">' + extra + '\n<link rel="stylesheet" href="css/studio.css">\n<link rel="stylesheet" href="css/concepts.css">\n<link rel="stylesheet" href="css/project-system.css">\n<link rel="preload" as="font" type="font/woff2" href="fonts/manrope-latin.woff2" crossorigin>\n<link rel="preload" as="font" type="font/woff2" href="fonts/ubuntu-mono-regular.woff2" crossorigin>\n</head>'

