def case(kind):
    data={
      'growth':('partner-growth-programs.html','Partner Growth<br>Programs.','Product Design Lead · Agoda','One hub for the whole<br>growth journey.','Owned design strategy end to end for Agoda’s partner growth program suite: from problem framing and stakeholder alignment to information architecture, interaction design and visual craft.','Every program funnel optimized its own metrics. Partners struggled to discover and compare programs, while complex programs attracted less traffic.', [('Design around the property, not the funnel.','A unified hub makes discovery and comparison part of one partner experience, with recommended actions and a full program catalog.'),('Give every program a common language.','Four co-owned tenets and seven lifecycle patterns align discovery, pre-activation confidence, activation, settings, analytics, deactivation and retention.'),('Align early. Scope the launch.','Weekly syncs with program owners surfaced tradeoffs. Partner research, support tickets and NPS informed the work; an impact/effort matrix shaped the MVP.')]),
      'discount':('discounting.html','Every discount.<br>Understood.','Senior Product Designer · Agoda','Make the economics<br>visible before commitment.','Led design for Discounting 2.0 across one of Agoda’s highest-revenue partner surfaces, aligning product and business owners while protecting the partner experience.','Partners could not tell how discounts stacked. Legacy promotions were confusing, and changes to this high-revenue surface involved conflicting stakeholder interests.', [('Show the calculation before commitment.','The Net Rate Simulator makes sequential discounting visible on the remaining balance, so a partner can understand the resulting room rate.'),('Explain the booking, night by night.','A reservation breakdown shows the promotion, percentage and monetary value for each night instead of forcing partners to reverse-engineer their earnings.'),('Teach the rule at the decision point.','Connect booker conditions to eligible promotions, then show their priority and sequence. Iterate through partner testing, feature-flagged experiments and support feedback.')]),
      'dev':('dev-portal.html','Less friction.<br>More building.','Senior Product Designer · Agoda Engineering','Give developers<br>a path they can follow.','Led 0-to-1 design for Developer Portal and Deployment as the first designer in DevOps, building domain understanding and a measurable foundation for developer experience.','The internal platform was fragmented and slow. A flat homepage and missing guidance made service creation depend on Slack and tribal knowledge, with no usability baseline.', [('Organize around the task.','Replace a flat link dump with Manage, Plan, Build, Secure and Monitor. A searchable catalog brings ownership, source and compliance into view.'),('Unblock first. Then automate.','Initial fixes added in-context guidance, skipped unused repository steps, and supported leave and resume during AD handoffs. Later work introduced automation and approval workflows.'),('Make deployment a reviewable decision.','A staged private-cloud flow covers environment setup, canary rollout across data centers, and review. Information hierarchy surfaces environments and critical actions.')])}
    route,title,role,thesis,myrole,problem,choices=data[kind]
    demo=discovery() if kind=='growth' else calculator() if kind=='discount' else developer()
    inspiration={'growth':'Shopify-inspired program discovery','discount':'Stripe-inspired calculation clarity','dev':'Vercel-inspired developer workflow'}[kind]
    extra=''
    if kind=='growth':
        extra='''<section class="supporting-artifacts"><div class="section-heading"><p class="eyebrow">Design system evidence</p><h2>Consistency across<br>the lifecycle.</h2></div><p>The original interactive playbook retains all seven patterns, their examples and the four co-owned tenets.</p><a class="text-link" href="originals/partner-growth-programs.html">Open the original lifecycle playbook &amp; product artifacts ↗</a></section>'''
    elif kind=='discount':
        extra='''<section class="supporting-artifacts"><div class="section-heading"><p class="eyebrow">Promotion breakdown · updated calculation example</p><h2>The same clarity,<br>night by night.</h2></div><div class="night-breakdown"><div><span>Night 1 · Mega Sale, 15%</span><strong>$150 − $22.50 = $127.50</strong></div><div><span>Night 2 · Mobile Exclusive, 10%</span><strong>$150 − $15.00 = $135.00</strong></div><div class="night-total"><span>Room rate after discounts · two nights</span><strong>$262.50</strong></div></div><p class="artifact-note">Illustrative example, before commission and taxes. The original artifact lists a $11.25 mobile discount on a $150 night at 10%; this updated example corrects that arithmetic to $15.00. Total discounts: $37.50.</p><a class="text-link" href="originals/discounting.html">View all three original product artifacts ↗</a></section>'''
    else:
        extra='''<section class="supporting-artifacts"><div class="section-heading"><p class="eyebrow">Research &amp; original artifacts</p><h2>Understand the blocker.<br>Then design the path.</h2></div><figure class="research-figure"><img src="images/dev_pc_research.png" width="972" height="1063" loading="lazy" decoding="async" alt="Original synthesis of developer interviews into recurring workflow themes"><figcaption>Original developer research synthesis. Full-size image and all catalog, deployment and service-detail artifacts remain accessible below.</figcaption></figure><a class="text-link" href="images/dev_pc_research.png">Open research image at full size ↗</a><a class="text-link" href="originals/dev-portal.html">View original research, before/after flow &amp; deployment screens ↗</a></section>'''
    body=f'''{nav('work')}<main id="main"><section class="case-hero case-hero--{kind}"><a class="back-link" href="projects.html">← Selected work</a><p class="eyebrow">{role}</p><h1>{title}</h1><p class="case-thesis">{thesis}</p><a class="case-scroll" href="#decisions">The decisions <span aria-hidden="true">↓</span></a></section><div class="case-body"><nav class="case-section-nav" aria-label="Case study sections"><a href="#decisions">Problem &amp; role</a><a href="#choices">Key choices</a><a href="#evidence">Evidence</a><a href="#concept">Try the concept <span aria-hidden="true">↗</span></a></nav><section class="case-framing" id="decisions"><div><p class="eyebrow">The problem</p><h2>{problem}</h2></div><div><p class="eyebrow">My role</p><p>{myrole}</p><a class="text-link" href="originals/{route}">Read the complete original case study ↗</a></div></section><section class="decisions-section" id="choices"><p class="eyebrow">Key choices</p>{''.join(f'<article class="decision"><span aria-hidden="true">↳</span><h3>{t}</h3><p>{d}</p></article>' for t,d in choices)}</section>{evidence(kind)}<section class="concept-section" id="concept"><div class="concept-heading"><div><p class="eyebrow">Updated concept · {inspiration}</p><h2>Explore the<br>design in action.</h2></div><a class="text-link" href="originals/{route}">Original artifacts ↗</a></div><p class="concept-context">A new visual exploration using the existing content and workflow. This is a portfolio concept, not an additional shipped contribution or measured outcome.</p><div class="concept-canvas concept-canvas--{kind}">{demo}</div></section>{extra}<div class="case-next"><a href="{'discounting.html' if kind=='growth' else 'dev-portal.html' if kind=='discount' else 'partner-growth-programs.html'}">Next case study <span aria-hidden="true">↗</span></a><a href="projects.html">All work</a></div></div></main>{footer()}'''
    write(route,body)

def write(name,body):
    (ROOT/name).write_text(head(name)+'\n<body class="folio">'+body+'\n<script type="module" src="js/folio.mjs"></script>\n</body>\n</html>\n',encoding='utf-8')

identity=flagship_hero()
write('index.html',nav()+f'<main id="main" class="portfolio-home">{identity}{project_showcase()}<div class="studio-divider" aria-hidden="true"><i></i><i></i><i></i></div>{about()}{archive()}</main>'+footer())
write('projects.html',nav('work')+'<main id="main"><section class="work-index-heading"><p class="eyebrow">Nicholas Gwee · Product Design Lead</p><h1>Selected work.</h1><p>Product strategy, interface craft and the evidence behind the work.</p></section>'+selected()+archive()+'</main>'+footer())
for kind in ['growth','discount','dev']: case(kind)

# Preserve the resume and its download/contact content; replace only its navigation.
resume=(ROOT/'resume.html').read_text(encoding='utf-8')
if 'site-nav' not in resume:
    resume=re.sub(r'<header class="header">.*?</header>',nav('resume'),resume,flags=re.S)
